use lightning_invoice::utils::create_invoice_from_channelmanager;

pub fn create_tip_invoice(amount_sats: u64) -> anyhow::Result<String> {
    let amount_msats = amount_sats * 1_000;
    let invoice = create_invoice_from_channelmanager(
        &channel_manager,
        keys_manager,
        logger,
        bitcoin::Network::Regtest,
        Some(amount_msats),
        "build-satoshi-tip".to_owned(),
        3600,
        None,
    )?;

    Ok(invoice.to_string())
