use lightning::events::Event;

pub fn handle_event(event: Event, tx: &tokio::sync::broadcast::Sender<String>) {
    if let Event::PaymentClaimable { payment_hash, amount_msat, .. } = event {
        let sats = amount_msat / 1_000;
        let payload = format!("event: paid\ndata: {}:{}\n\n", payment_hash, sats);
        let _ = tx.send(payload);
    }
}

