final walletProvider = FutureProvider<WalletSnapshot>((ref) async {
  final wallet = await ref.watch(walletServiceProvider.future);
  final blockchain = await EsploraClient.create(baseUrl: 'https://blockstream.info/testnet/api');

  await wallet.sync(blockchain: blockchain);

  return WalletSnapshot(
    balance: await wallet.getBalance(),
    utxos: await wallet.listUnspent(),
    transactions: await wallet.listTransactions(),
  );
});

class VaultService {
  Script buildCltvVault({required String pubkey, required int lockHeight}) {
    return ScriptBuilder()
        .addInt(lockHeight)
        .addOp(Opcode.opCheckLockTimeVerify)
        .addOp(Opcode.opDrop)
        .addData(pubkey)
        .addOp(Opcode.opCheckSig)
        .asScript();
  }
}

class StreakService {
  Future<int> updateStreak(DateTime now, SharedPreferences prefs) async {
    final lastDeposit = prefs.getString('last_deposit_at');
    final current = prefs.getInt('current_streak') ?? 0;
    final next = _isConsecutive(lastDeposit, now) ? current + 1 : 1;

    await prefs.setString('last_deposit_at', now.toIso8601String());
    await prefs.setInt('current_streak', next);
    return next;
  }
}

