class PriceService {
  final client = HttpClient();

  Future<double> fetchBtcNgn() async {
    final request = await client.getUrl(Uri.parse('https://api.binance.com/api/v3/ticker/price?symbol=BTCNGN'));
    final response = await request.close();
    final payload = jsonDecode(await response.transform(utf8.decoder).join());
    return double.parse(payload['price'] as String);
  }
}

