use bitcoin::consensus::deserialize;
use bitcoin::psbt::Psbt;

fn main() -> anyhow::Result<()> {
    let raw = std::env::args().nth(1).expect("missing psbt");
    let bytes = hex::decode(raw)?;
    let psbt: Psbt = deserialize(&bytes)?;

    println!("inputs: {}", psbt.inputs.len());
    println!("outputs: {}", psbt.outputs.len());
    println!("unsigned tx: {:#?}", psbt.unsigned_tx);
    Ok(())
}

use serde::Deserialize;

#[derive(Clone, Deserialize)]
struct TxOut {
    value: u64,
    scriptpubkey: String,
}

#[derive(Deserialize)]
struct EsploraTx {
    vout: Vec<TxOut>,
}

pub async fn fetch_prevout(txid: &str, vout: usize) -> anyhow::Result<TxOut> {
    let url = format!("https://blockstream.info/testnet/api/tx/{txid}");
    let response = reqwest::get(url).await?;
    let tx = response.json::<EsploraTx>().await?;
    Ok(tx.vout[vout].clone())
}

use bitcoin::key::TapTweak;
use bitcoin::secp256k1::{Keypair, Secp256k1, SecretKey};

pub fn taproot_keypair(secret_hex: &str) -> anyhow::Result<Keypair> {
    let secp = Secp256k1::new();
    let secret = SecretKey::from_slice(&hex::decode(secret_hex)?)?;
    let keypair = Keypair::from_secret_key(&secp, &secret);
    Ok(keypair.tap_tweak(&secp, None).to_inner())
}

pub async fn broadcast_tx(hex_tx: &str) -> anyhow::Result<String> {
    let response = reqwest::Client::new()
        .post("https://mempool.space/testnet/api/tx")
        .body(hex_tx.to_owned())
        .send()
        .await?;

    Ok(response.text().await?)
}

use std::process::Command;

pub fn sign_with_hwi(fingerprint: &str, psbt_path: &str) -> anyhow::Result<String> {
    let output = Command::new("hwi")
        .args(["-f", fingerprint, "signtx", psbt_path])
        .output()?;

    Ok(String::from_utf8(output.stdout)?)
}

